export const GetDashboardSummaryResponse = zod.object({
  totalClients: zod.number(),
  totalActiveClients: zod.number(),
  totalCompletedToday: zod.number(),
  totalBranches: zod.number(),
  totalHunters: zod.number(),
  totalProducts: zod.number(),
  completedThisMonth: zod.number(),
  rejectedThisMonth: zod.number(),
});

/**
 * @summary Get recent activity feed
 */
export const GetRecentActivityQueryParams = zod.object({
  limit: zod.coerce.number().optional(),
});

export const GetRecentActivityResponseItem = zod.object({
  id: zod.number(),
  type: zod.string(),
  description: zod.string(),
  entityId: zod.number().nullish(),
  entityType: zod.string().nullish(),
  userId: zod.number().nullish(),
  userName: zod.string().nullish(),
  branchName: zod.string().nullish(),
  createdAt: zod.coerce.date(),
});
export const GetRecentActivityResponse = zod.array(
  GetRecentActivityResponseItem,
);

/**
 * @summary Get per-branch statistics
 */
export const GetBranchStatsResponseItem = zod.object({
  branchId: zod.number(),
  branchName: zod.string(),
  totalClients: zod.number(),
  completedClients: zod.number(),
  activeHunters: zod.number(),
});
export const GetBranchStatsResponse = zod.array(GetBranchStatsResponseItem);

/**
 * @summary Get client status breakdown counts
 */
export const GetClientStatusBreakdownResponseItem = zod.object({
  status: zod.string(),
  count: zod.number(),
});
export const GetClientStatusBreakdownResponse = zod.array(
  GetClientStatusBreakdownResponseItem,
);
